  1	package com.pousada.marealta.service;
  2	
  3	import com.pousada.marealta.model.Message;
  4	import com.pousada.marealta.util.EmailValidator;
  5	import java.util.*;
  6	import java.util.concurrent.atomic.AtomicLong;
  7	
  8	public class MessageService {
  9	    private final List<Message> messages = new ArrayList<>();
 10	    private final AtomicLong nextId = new AtomicLong(1);
 11	    private final boolean testMode;
 12	
 13	    public MessageService(boolean testMode) {
 14	        this.testMode = testMode;
 15	    }
 16	
 17	    public Message sendMessage(String channel, String to, String subject, String body) {
 18	        String status = "SENT";
 19	        String finalTo = to;
 20	        String finalSubject = subject;
 21	        String finalBody = body;
 22	
 23	        if (!EmailValidator.isValid(to)) {
 24	            status = "BLOCKED";
 25	            addMessage(channel, to, subject, body, status);
 26	            return new Message(nextId.get() - 1, channel, to, subject, body, status);
 27	        }
 28	
 29	        if (testMode) {
 30	            finalTo = "testes@pousadamarealta.com.br";
 31	            finalSubject = "[TESTE] " + subject;
 32	            finalBody = "Destinatário original: " + to + "\n\n" + body;
 33	        }
 34	
 35	        long id = addMessage(channel, finalTo, finalSubject, finalBody, status);
 36	
 37	        if (!testMode) {
 38	            String archiveSubject = "[Cópia] " + subject;
 39	            addMessage(channel, "arquivo@pousadamarealta.com.br", archiveSubject, body, status);
 40	        }
 41	
 42	        return new Message(id, channel, finalTo, finalSubject, finalBody, status);
 43	    }
 44	
 45	    private long addMessage(String channel, String to, String subject, String body, String status) {
 46	        long id = nextId.getAndIncrement();
 47	        messages.add(new Message(id, channel, to, subject, body, status));
 48	        return id;
 49	    }
 50	
 51	    public List<Message> getAllMessages() {
 52	        return new ArrayList<>(messages);
 53	    }
 54	}
 55	package com.pousada.marealta.util;
 56	
 57	public class EmailValidator {
 58	    public static boolean isValid(String email) {
 59	        if (email == null || email.isEmpty()) {
 60	            return false;
 61	        }
 62	
 63	        int atCount = 0;
 64	        int atIndex = -1;
 65	        for (int i = 0; i < email.length(); i++) {
 66	            if (email.charAt(i) == '@') {
 67	                atCount++;
 68	                atIndex = i;
 69	            }
 70	        }
 71	
 72	        if (atCount != 1 || atIndex <= 0) {
 73	            return false;
 74	        }
 75	
 76	        String domain = email.substring(atIndex + 1);
 77	        return domain.contains(".") && domain.indexOf('.') < domain.length() - 1;
 78	    }
 79	}
