106	package com.pousada.marealta;
107	
108	import com.fasterxml.jackson.databind.ObjectMapper;
109	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
110	import com.google.gson.Gson;
111	import com.google.gson.GsonBuilder;
112	import com.pousada.marealta.api.converter.*;
113	import com.pousada.marealta.api.dto.*;
114	import com.pousada.marealta.model.*;
115	import com.pousada.marealta.service.*;
116	import com.pousada.marealta.util.DateUtil;
117	import com.pousada.marealta.util.DocumentFormatter;
118	import io.javalin.Javalin;
119	import io.javalin.http.ContentType;
120	import io.javalin.json.JsonMapper;
121	import java.lang.reflect.Type;
122	import java.math.BigDecimal;
123	import java.time.LocalDate;
124	import java.time.YearMonth;
125	
126	public class App {
127	    private final Javalin app;
128	    private final RoomManager roomManager;
129	    private final ReservationService reservationService;
130	    private final MessageService messageService;
131	    private final ReportService reportService;
132	    private final Gson gson;
133	
134	    public App() {
135	        this.gson = new GsonBuilder()
136	            .setPrettyPrinting()
137	            .create();
138	
139	        this.roomManager = new RoomManager();
140	        this.reservationService = new ReservationService(roomManager);
141	
142	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
143	        this.messageService = new MessageService(testMode);
144	        this.reportService = new ReportService(reservationService, roomManager);
145	
146	        ObjectMapper mapper = new ObjectMapper();
147	        JavaTimeModule javaTimeModule = new JavaTimeModule();
148	        mapper.registerModule(javaTimeModule);
149	        mapper.configure(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
150	
151	        this.app = Javalin.create(config -> {
152	            config.jsonMapper(new JsonMapper() {
153	                @Override
154	                public <T> T fromJsonString(String json, Type targetType) {
155	                    try {
156	                        return mapper.readValue(json, mapper.constructType(targetType));
157	                    } catch (Exception e) {
158	                        throw new RuntimeException(e);
159	                    }
160	                }
161	
162	                @Override
163	                public String toJsonString(Object obj, Type type) {
164	                    try {
165	                        return mapper.writeValueAsString(obj);
166	                    } catch (Exception e) {
167	                        throw new RuntimeException(e);
168	                    }
169	                }
170	            });
171	        });
172	        setupRoutes();
173	    }
174	
175	    private void setupRoutes() {
176	        app.get("/rooms", ctx -> {
177	            var rooms = roomManager.getAllRooms().stream()
178	                .map(RoomConverter::toDto)
179	                .toList();
180	            ctx.json(rooms);
181	        });
182	
183	        app.post("/reservations", ctx -> {
184	            try {
185	                CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
186	
187	                RatePlan ratePlan = RatePlan.valueOf(req.ratePlan());
188	                Reservation reservation = reservationService.createReservation(
189	                    req.roomNumber(),
190	                    req.guestName(),
191	                    req.guestEmail(),
192	                    req.guestCpf(),
193	                    req.checkIn(),
194	                    req.checkOut(),
195	                    req.guests(),
196	                    ratePlan
197	                );
198	
199	                ctx.status(201);
200	                ctx.json(ReservationConverter.toDto(reservation));
201	            } catch (ReservationService.ValidationException e) {
202	                handleValidationError(ctx, e.code, e.getMessage());
203	            } catch (IllegalArgumentException e) {
204	                ctx.status(400);
205	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Plano de tarifa inválido"));
206	            }
207	        });
208	
209	        app.get("/reservations/{id}", ctx -> {
210	            try {
211	                long id = Long.parseLong(ctx.pathParam("id"));
212	                Reservation reservation = reservationService.getReservation(id)
213	                    .orElseThrow(() -> new ReservationService.ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
214	                ctx.json(ReservationConverter.toDto(reservation));
215	            } catch (ReservationService.ValidationException e) {
216	                handleValidationError(ctx, e.code, e.getMessage());
217	            }
218	        });
219	
220	        app.post("/reservations/{id}/confirmation", ctx -> {
221	            try {
222	                long id = Long.parseLong(ctx.pathParam("id"));
223	                ConfirmationRequest req = ctx.bodyAsClass(ConfirmationRequest.class);
224	
225	                reservationService.confirmReservation(id, req.amountPaid());
226	
227	                Reservation reservation = reservationService.getReservation(id).orElseThrow();
228	
229	                var document = DocumentConverter.toDocument(reservation, roomManager);
230	                String documentText = DocumentFormatter.formatDocument(document);
231	                String emailBody = formatConfirmationEmail(reservation.getGuestName(), documentText);
232	
233	                messageService.sendMessage(
234	                    "EMAIL",
235	                    reservation.getGuestEmail(),
236	                    "Reserva confirmada - Pousada Maré Alta",
237	                    emailBody
238	                );
239	
240	                ctx.json(ReservationConverter.toDto(reservation));
241	            } catch (ReservationService.ValidationException e) {
242	                handleValidationError(ctx, e.code, e.getMessage());
243	            }
244	        });
245	
246	        app.post("/reservations/{id}/cancellation", ctx -> {
247	            try {
248	                long id = Long.parseLong(ctx.pathParam("id"));
249	                reservationService.cancelReservation(id);
250	
251	                Reservation reservation = reservationService.getReservation(id).orElseThrow();
252	                ctx.json(ReservationConverter.toDto(reservation));
253	            } catch (ReservationService.ValidationException e) {
254	                handleValidationError(ctx, e.code, e.getMessage());
255	            }
256	        });
257	
258	        app.post("/reservations/{id}/check-in", ctx -> {
259	            try {
260	                long id = Long.parseLong(ctx.pathParam("id"));
261	                reservationService.checkin(id);
262	
263	                Reservation reservation = reservationService.getReservation(id).orElseThrow();
264	                ctx.json(ReservationConverter.toDto(reservation));
265	            } catch (ReservationService.ValidationException e) {
266	                handleValidationError(ctx, e.code, e.getMessage());
267	            }
268	        });
269	
270	        app.post("/reservations/{id}/check-out", ctx -> {
271	            try {
272	                long id = Long.parseLong(ctx.pathParam("id"));
273	                reservationService.checkout(id);
274	
275	                Reservation reservation = reservationService.getReservation(id).orElseThrow();
276	                var document = DocumentConverter.toDocument(reservation, roomManager);
277	                DocumentDto documentDto = DocumentConverter.toDto(document);
278	
279	                ctx.json(documentDto);
280	            } catch (ReservationService.ValidationException e) {
281	                handleValidationError(ctx, e.code, e.getMessage());
282	            }
283	        });
284	
285	        app.get("/reservations/{id}/document", ctx -> {
286	            try {
287	                long id = Long.parseLong(ctx.pathParam("id"));
288	                Reservation reservation = reservationService.getReservation(id)
289	                    .orElseThrow(() -> new ReservationService.ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
290	
291	                if (reservation.getStatus() == ReservationStatus.PENDING) {
292	                    throw new ReservationService.ValidationException("OPERATION_NOT_ALLOWED", "Documento só disponível para reservas pagas");
293	                }
294	
295	                var document = DocumentConverter.toDocument(reservation, roomManager);
296	                DocumentDto documentDto = DocumentConverter.toDto(document);
297	
298	                ctx.json(documentDto);
299	            } catch (ReservationService.ValidationException e) {
300	                handleValidationError(ctx, e.code, e.getMessage());
301	            }
302	        });
303	
304	        app.get("/messages", ctx -> {
305	            var messages = messageService.getAllMessages().stream()
306	                .map(MessageConverter::toDto)
307	                .toList();
308	            ctx.json(messages);
309	        });
310	
311	        app.get("/reports/occupancy", ctx -> {
312	            String dateStr = ctx.queryParam("date");
313	            if (dateStr == null || dateStr.isEmpty()) {
314	                ctx.status(400);
315	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'date' é obrigatório"));
316	                return;
317	            }
318	
319	            try {
320	                LocalDate date = LocalDate.parse(dateStr);
321	                String report = reportService.generateOccupancyReport(date);
322	                ctx.contentType(ContentType.TEXT_PLAIN);
323	                ctx.header("Content-Type", "text/csv;charset=utf-8");
324	                ctx.result(report);
325	            } catch (Exception e) {
326	                ctx.status(400);
327	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Data em formato inválido"));
328	            }
329	        });
330	
331	        app.get("/reports/revenue", ctx -> {
332	            String monthStr = ctx.queryParam("month");
333	            if (monthStr == null || monthStr.isEmpty()) {
334	                ctx.status(400);
335	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'month' é obrigatório"));
336	                return;
337	            }
338	
339	            try {
340	                YearMonth yearMonth = YearMonth.parse(monthStr);
341	                String report = reportService.generateRevenueReport(yearMonth);
342	                ctx.contentType(ContentType.TEXT_PLAIN);
343	                ctx.header("Content-Type", "text/csv;charset=utf-8");
344	                ctx.result(report);
345	            } catch (Exception e) {
346	                ctx.status(400);
347	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Mês em formato inválido"));
348	            }
349	        });
350	    }
351	
352	    private void handleValidationError(io.javalin.http.Context ctx, String code, String message) {
353	        ctx.status(getStatusCode(code));
354	        ctx.json(new ErrorResponse(code, message));
355	    }
356	
357	    private int getStatusCode(String code) {
358	        return switch (code) {
359	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
360	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
361	            case "CAPACITY_EXCEEDED" -> 422;
362	            default -> 400;
363	        };
364	    }
365	
366	    private String formatConfirmationEmail(String guestName, String documentText) {
367	        return "Olá, " + guestName + "!\n\n" +
368	               "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
369	               documentText + "\n" +
370	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
371	               "Até breve!";
372	    }
373	
374	    public void start() {
375	        String portStr = System.getenv("PORT");
376	        int port = (portStr != null) ? Integer.parseInt(portStr) : 7070;
377	        app.start(port);
378	    }
379	
380	    public Javalin getApp() {
381	        return app;
382	    }
383	
384	    public static void main(String[] args) {
385	        App app = new App();
386	        app.start();
387	    }
388	}

