     9	public class ReservationService {
    10	    private final RoomManager roomManager;
    11	    private final Map<Long, Reservation> reservations = new HashMap<>();
    12	    private final AtomicLong nextId = new AtomicLong(1);
    13	
    14	    public ReservationService(RoomManager roomManager) {
    15	        this.roomManager = roomManager;
    16	    }
    17	
    18	    public Reservation createReservation(
    19	        int roomNumber,
    20	        String guestName,
    21	        String guestEmail,
    22	        String guestCpf,
    23	        LocalDate checkIn,
    24	        LocalDate checkOut,
    25	        int guests,
    26	        RatePlan ratePlan
    27	    ) throws ValidationException {
    28	        var room = roomManager.getRoom(roomNumber)
    29	            .orElseThrow(() -> new ValidationException("ROOM_NOT_FOUND", "Quarto não encontrado"));
    30	
    31	        if (checkIn.isAfter(checkOut)) {
    32	            throw new ValidationException("INVALID_REQUEST", "Data de saída não pode ser antes da entrada");
    33	        }
    34	
    35	        if (guests < 1) {
    36	            throw new ValidationException("INVALID_REQUEST", "Pelo menos 1 hóspede é obrigatório");
    37	        }
    38	
    39	        if (guests > room.capacity()) {
    40	            throw new ValidationException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto");
    41	        }
    42	
    43	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, -1)) {
    44	            throw new ValidationException("ROOM_UNAVAILABLE", "Quarto não disponível para essas datas");
    45	        }
    46	
    47	        var pricing = PricingService.calculate(room, checkIn, checkOut, ratePlan);
    48	
    49	        long id = nextId.getAndIncrement();
    50	        Reservation reservation = new Reservation(
    51	            id,
    52	            roomNumber,
    53	            guestName,
    54	            guestEmail,
    55	            guestCpf,
    56	            checkIn,
    57	            checkOut,
    58	            guests,
    59	            ratePlan,
    60	            pricing.nights,
    61	            pricing.subtotal,
