279	    28	    public static PriceCalculation calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
280	    29	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
281	    30	
