     1	package com.pousada.marealta.service;
     2	
     3	import com.pousada.marealta.model.RatePlan;
     4	import com.pousada.marealta.model.Room;
     5	import com.pousada.marealta.util.DateUtil;
     6	import com.pousada.marealta.util.MoneyUtil;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	
    10	public class PricingService {
    11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    13	
    14	    public static class PriceCalculation {
    15	        public final int nights;
    16	        public final BigDecimal subtotal;
    17	        public final BigDecimal discount;
    18	        public final BigDecimal total;
    19	
    20	        public PriceCalculation(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    21	            this.nights = nights;
    22	            this.subtotal = subtotal;
    23	            this.discount = discount;
    24	            this.total = total;
    25	        }
    26	    }
    27	
    28	    public static PriceCalculation calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    29	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    30	
    31	        BigDecimal nightlyRate = room.nightlyRate();
    32	        BigDecimal subtotal = BigDecimal.ZERO;
    33	
    34	        for (int i = 0; i < nights; i++) {
    35	            LocalDate date = checkIn.plusDays(i);
    36	            BigDecimal nightRate = nightlyRate;
    37	            if (DateUtil.isHighSeason(date)) {
    38	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER);
    39	            }
    40	            nightRate = MoneyUtil.roundHalfEven(nightRate);
    41	            subtotal = subtotal.add(nightRate);
    42	        }
    43	
    44	        subtotal = MoneyUtil.roundHalfEven(subtotal);
    45	
    46	        BigDecimal discount = BigDecimal.ZERO;
    47	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    48	            discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
    49	            discount = MoneyUtil.roundHalfEven(discount);
    50	        }
    51	
    52	        BigDecimal total = subtotal.subtract(discount);
    53	        total = MoneyUtil.roundHalfEven(total);
    54	
    55	        return new PriceCalculation(nights, subtotal, discount, total);
    56	    }
    57	}
