     1	package com.pousada.marealta.service;
     2	
     3	import com.pousada.marealta.model.Reservation;
     4	import com.pousada.marealta.model.ReservationStatus;
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	public class ReportService {
    12	    private final ReservationService reservationService;
    13	    private final RoomManager roomManager;
    14	
    15	    public ReportService(ReservationService reservationService, RoomManager roomManager) {
    16	        this.reservationService = reservationService;
    17	        this.roomManager = roomManager;
    18	    }
    19	
    20	    public String generateOccupancyReport(LocalDate date) {
    21	        StringBuilder csv = new StringBuilder();
    22	        csv.append("room,type,reservation,check_in,check_out\n");
    23	
    24	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
    25	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    26	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
    27	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
    28	            .filter(r -> !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut()))
    29	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
    30	            .toList();
    31	
    32	        for (Reservation r : occupiedReservations) {
    33	            var room = roomManager.getRoom(r.getRoomNumber()).orElseThrow();
    34	            csv.append(r.getRoomNumber()).append(",");
    35	            csv.append(room.type()).append(",");
    36	            csv.append(r.getId()).append(",");
    37	            csv.append(r.getCheckIn()).append(",");
    38	            csv.append(r.getCheckOut()).append("\n");
    39	        }
    40	
    41	        int totalRooms = (int) roomManager.getAllRooms().stream().count();
    42	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms).append("\n");
    43	
    44	        return csv.toString();
    45	    }
    46	
    47	    public String generateRevenueReport(YearMonth yearMonth) {
    48	        StringBuilder csv = new StringBuilder();
    49	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
    52	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(yearMonth))
    53	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    54	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
    55	                        r.getStatus() == ReservationStatus.CHECKED_OUT ||
    56	                        r.getStatus() == ReservationStatus.CANCELLED)
    57	            .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0 ||
    58	                        (r.getRefund() != null && r.getRefund().compareTo(BigDecimal.ZERO) > 0))
    59	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    60	                .thenComparingLong(Reservation::getId))
    61	            .toList();
    62	
    63	        BigDecimal totalAmount = BigDecimal.ZERO;
    64	        for (Reservation r : monthReservations) {
    65	            BigDecimal amount = r.getAmountPaid();
    66	            if (r.getRefund() != null) {
    67	                amount = amount.subtract(r.getRefund());
    68	            }
    69	
    70	            csv.append(r.getId()).append(",");
    71	            csv.append(r.getRoomNumber()).append(",");
    72	            csv.append(r.getCheckIn()).append(",");
    73	            csv.append(r.getCheckOut()).append(",");
    74	            csv.append(r.getStatus()).append(",");
    75	            csv.append(String.format("%.2f", amount)).append("\n");
    76	
    77	            totalAmount = totalAmount.add(amount);
    78	        }
    79	
    80	        csv.append("total,").append(String.format("%.2f", totalAmount)).append("\n");
    81	
    82	        return csv.toString();
    83	    }
    84	}
