    11	    private final Map<Long, Reservation> reservations = new HashMap<>();
    12	    private final AtomicLong nextId = new AtomicLong(1);
    13	
    14	    public ReservationService(RoomManager roomManager) {
    15	        this.roomManager = roomManager;
    16	    }
    17	
    18	    public Reservation createReservation(
    19	        int roomNumber,
    20	        String guestName,
    21	        String guestEmail,
    22	        String guestCpf,
    23	        LocalDate checkIn,
    24	        LocalDate checkOut,
    25	        int guests,
    26	        RatePlan ratePlan
    27	    ) throws ValidationException {
    28	        var room = roomManager.getRoom(roomNumber)
    29	            .orElseThrow(() -> new ValidationException("ROOM_NOT_FOUND", "Quarto não encontrado"));
    30	
    31	        if (checkIn.isAfter(checkOut)) {
    32	            throw new ValidationException("INVALID_REQUEST", "Data de saída não pode ser antes da entrada");
    33	        }
    34	
    35	        if (guests < 1) {
    36	            throw new ValidationException("INVALID_REQUEST", "Pelo menos 1 hóspede é obrigatório");
    37	        }
    38	
    39	        if (guests > room.capacity()) {
    40	            throw new ValidationException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto");
    41	        }
    42	
    43	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, -1)) {
    44	            throw new ValidationException("ROOM_UNAVAILABLE", "Quarto não disponível para essas datas");
    45	        }
    46	
    47	        var pricing = PricingService.calculate(room, checkIn, checkOut, ratePlan);
    48	
    49	        long id = nextId.getAndIncrement();
    50	        Reservation reservation = new Reservation(
    51	            id,
    52	            roomNumber,
    53	            guestName,
    54	            guestEmail,
    55	            guestCpf,
    56	            checkIn,
    57	            checkOut,
    58	            guests,
    59	            ratePlan,
    60	            pricing.nights,
    61	            pricing.subtotal,
    62	            pricing.discount,
    63	            pricing.total
    64	        );
    65	
    66	        reservations.put(id, reservation);
    67	        return reservation;
    68	    }
    69	
    70	    public Optional<Reservation> getReservation(long id) {
    71	        return Optional.ofNullable(reservations.get(id));
    72	    }
    73	
    74	    public List<Reservation> getAllReservations() {
    75	        return new ArrayList<>(reservations.values());
    76	    }
    77	
    78	    public void confirmReservation(long id, BigDecimal amountPaid) throws ValidationException {
    79	        Reservation reservation = getReservation(id)
    80	            .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
    81	
    82	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    83	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Só é possível confirmar uma reserva pendente");
    84	        }
    85	
    86	        reservation.setStatus(ReservationStatus.CONFIRMED);
    87	        reservation.setAmountPaid(amountPaid);
    88	    }
    89	
    90	    public void checkin(long id) throws ValidationException {
    91	        Reservation reservation = getReservation(id)
    92	            .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
    93	
    94	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    95	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Só é possível fazer check-in de uma reserva confirmada");
    96	        }
    97	
    98	        reservation.setStatus(ReservationStatus.CHECKED_IN);
    99	    }
   100	
   101	    public void checkout(long id) throws ValidationException {
   102	        Reservation reservation = getReservation(id)
   103	            .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
   104	
   105	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   106	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Só é possível fazer check-out de uma reserva com check-in realizado");
   107	        }
   108	
   109	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   110	    }
   111	
   112	    public void cancelReservation(long id) throws ValidationException {
   113	        Reservation reservation = getReservation(id)
   114	            .orElseThrow(() -> new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
   115	
   116	        ReservationStatus status = reservation.getStatus();
   117	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   118	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Só é possível cancelar uma reserva pendente ou confirmada");
   119	        }
   120	
   121	        BigDecimal refund = BigDecimal.ZERO;
   122	        if (status == ReservationStatus.CONFIRMED) {
   123	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
   124	                refund = reservation.getAmountPaid();
   125	            }
   126	        }
   127	
   128	        reservation.setStatus(ReservationStatus.CANCELLED);
   129	        if (status == ReservationStatus.CONFIRMED) {
   130	            reservation.setRefund(refund);
   131	        }
   132	    }
   133	
   134	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, long excludeReservationId) {
   135	        LocalDate current = checkIn;
   136	        while (current.isBefore(checkOut)) {
   137	            for (Reservation res : reservations.values()) {
   138	                if (res.getId() == excludeReservationId) {
   139	                    continue;
   140	                }
   141	
   142	                if (res.getStatus() == ReservationStatus.CANCELLED) {
   143	                    continue;
   144	                }
   145	
   146	                if (res.getRoomNumber() == roomNumber &&
   147	                    !current.isBefore(res.getCheckIn()) &&
   148	                    current.isBefore(res.getCheckOut())) {
   149	                    return true;
   150	                }
   151	            }
   152	            current = current.plusDays(1);
   153	        }
   154	        return false;
   155	    }
   156	
   157	    public static class ValidationException extends Exception {
   158	        public final String code;
   159	
   160	        public ValidationException(String code, String message) {
   161	            super(message);
   162	            this.code = code;
   163	        }
   164	    }
   165	}
