     7	public class DocumentFormatter {
     8	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
     9	
    10	    public static String formatDocument(ReservationDocument doc) {
    11	        StringBuilder sb = new StringBuilder();
    12	        sb.append("Comprovante de reserva nº ").append(doc.reservationId()).append("\n");
    13	        sb.append("Hóspede: ").append(doc.guestName());
    14	        sb.append(" (CPF ").append(formatCpf(doc.guestCpf())).append(")\n");
    15	        sb.append("Quarto: ").append(doc.roomNumber()).append(" (").append(doc.roomType()).append(")\n");
    16	        sb.append("Entrada: ").append(doc.checkIn().format(DATE_FORMAT));
    17	        sb.append(" | Saída: ").append(doc.checkOut().format(DATE_FORMAT));
    18	        String nightsLabel = doc.nights() == 1 ? "1 diária" : doc.nights() + " diárias";
    19	        sb.append(" | ").append(nightsLabel).append("\n");
    20	        sb.append("Diárias: ").append(formatMoney(doc.subtotal())).append("\n");
    21	
    22	        if (doc.discount().compareTo(BigDecimal.ZERO) > 0) {
    23	            sb.append("Desconto: ").append(formatMoney(doc.discount())).append("\n");
    24	        }
    25	
    26	        sb.append("Total: ").append(formatMoney(doc.total())).append("\n");
    27	
    28	        return sb.toString();
    29	    }
    30	
    31	    public static String formatMoney(BigDecimal amount) {
    32	        return "R$ " + String.format("%.2f", amount).replace('.', ',');
    33	    }
    34	
    35	    public static String formatCpf(String cpf) {
    36	        if (cpf.length() == 11) {
    37	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    38	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    39	        }
    40	        return cpf;
    41	    }
    42	}
